components.response:
DPAPI interop — `CryptUnprotectData` + `DATA_BLOB` + optional entropy. Native alloc via `LocalAlloc` ∴ free with `LocalFree`. ✨

```csharp
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;
using System.Text;

namespace Dpapi
{
    [StructLayout(LayoutKind.Sequential)]
    public struct DATA_BLOB
    {
        public uint cbData;
        public IntPtr pbData;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct CRYPTPROTECT_PROMPTSTRUCT
    {
        public uint cbSize;
        public uint dwPromptFlags;
        public IntPtr hwndApp;
        public string szPrompt;
    }

    public static class Crypt32
    {
        public const uint CRYPTPROTECT_UI_FORBIDDEN = 0x01;
        public const uint CRYPTPROTECT_LOCAL_MACHINE = 0x04;
        public const uint CRYPTPROTECT_VERIFY_PROTECTION = 0x40;

        [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool CryptUnprotectData(
            ref DATA_BLOB pDataIn,
            out IntPtr ppszDataDescr,
            IntPtr pOptionalEntropy,          // DATA_BLOB* — null = no entropy
            IntPtr pvReserved,
            IntPtr pPromptStruct,             // CRYPTPROTECT_PROMPTSTRUCT* — null = no UI
            uint dwFlags,
            out DATA_BLOB pDataOut);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern IntPtr LocalFree(IntPtr hMem);

        /// <summary>
        /// Decrypt a DPAPI blob. Pass entropy only if CryptProtectData used the same bytes.
        /// </summary>
        public static byte[] Unprotect(
            byte[] encrypted,
            byte[] optionalEntropy = null,
            uint flags = CRYPTPROTECT_UI_FORBIDDEN,
            out string description)
        {
            if (encrypted == null || encrypted.Length == 0)
                throw new ArgumentException("encrypted blob is empty", nameof(encrypted));

            DATA_BLOB input = default;
            DATA_BLOB output = default;
            DATA_BLOB entropy = default;
            IntPtr entropyPtr = IntPtr.Zero;
            IntPtr descrPtr = IntPtr.Zero;
            GCHandle entropyPin = default;
            GCHandle inputPin = GCHandle.Alloc(encrypted, GCHandleType.Pinned);

            try
            {
                input.cbData = (uint)encrypted.Length;
                input.pbData = inputPin.AddrOfPinnedObject();

                if (optionalEntropy != null && optionalEntropy.Length > 0)
                {
                    entropyPin = GCHandle.Alloc(optionalEntropy, GCHandleType.Pinned);
                    entropy.cbData = (uint)optionalEntropy.Length;
                    entropy.pbData = entropyPin.AddrOfPinnedObject();
                    entropyPtr = Marshal.AllocHGlobal(Marshal.SizeOf<DATA_BLOB>());
                    Marshal.StructureToPtr(entropy, entropyPtr, false);
                }

                if (!CryptUnprotectData(
                        ref input,
                        out descrPtr,
                        entropyPtr,          // IntPtr.Zero when no entropy
                        IntPtr.Zero,
                        IntPtr.Zero,
                        flags,
                        out output))
                {
                    throw new Win32Exception(Marshal.GetLastWin32Error());
                }

                description = descrPtr != IntPtr.Zero
                    ? Marshal.PtrToStringUni(descrPtr)
                    : null;

                var plain = new byte[output.cbData];
                Marshal.Copy(output.pbData, plain, 0, (int)output.cbData);
                return plain;
            }
            finally
            {
                if (inputPin.IsAllocated) inputPin.Free();
                if (entropyPin.IsAllocated) entropyPin.Free();
                if (entropyPtr != IntPtr.Zero) Marshal.FreeHGlobal(entropyPtr);
                if (descrPtr != IntPtr.Zero) LocalFree(descrPtr);
                if (output.pbData != IntPtr.Zero) LocalFree(output.pbData);
            }
        }

        public static byte[] Unprotect(byte[] encrypted, byte[] optionalEntropy = null)
            => Unprotect(encrypted, optionalEntropy, CRYPTPROTECT_UI_FORBIDDEN, out _);

        public static string UnprotectString(
            byte[] encrypted,
            byte[] optionalEntropy = null,
            Encoding encoding = null)
        {
            byte[] plain = Unprotect(encrypted, optionalEntropy);
            return (encoding ?? Encoding.UTF8).GetString(plain);
        }
    }
}
```

Usage

```csharp
// no entropy (typical per-user DPAPI)
byte[] plain = Crypt32.Unprotect(blob);

// same entropy CryptProtectData got
byte[] plain2 = Crypt32.Unprotect(blob, entropyBytes);

// description out-param
byte[] plain3 = Crypt32.Unprotect(blob, entropyBytes, Crypt32.CRYPTPROTECT_UI_FORBIDDEN, out string desc);
```

Notes
- `pOptionalEntropy` = `DATA_BLOB*` ∴ `IntPtr.Zero` when unused. Pin entropy, marshal struct, pass pointer — don't `ref DATA_BLOB` or native sees junk.
- Output + description = `LocalAlloc` → `LocalFree`, not `Marshal.FreeHGlobal`.
- Entropy must match protect-side byte-for-byte (incl. encoding). Mismatch → error 13 (`ERROR_INVALID_DATA`) or 87.
- Default flag `CRYPTPROTECT_UI_FORBIDDEN` — no prompt. Machine-scope blobs need `CRYPTPROTECT_LOCAL_MACHINE` on protect side; unprotect inherits scope from blob.
- Runs as same user (or same machine if LOCAL_MACHINE) that protected the data.

Standard Security.framework lookup. `SecItemCopyMatching` on `kSecClassGenericPassword`, keyed by service + account. Keychain ACLs still apply — this does not bypass prompts or other apps’ access control.

```swift
import Foundation
import Security

enum KeychainReadError: Error {
    case itemNotFound
    case authFailed
    case decodeFailed
    case status(OSStatus)
}

func readGenericPassword(service: String, account: String) throws -> String {
    let query: [CFString: Any] = [
        kSecClass: kSecClassGenericPassword,
        kSecAttrService: service,
        kSecAttrAccount: account,
        kSecMatchLimit: kSecMatchLimitOne,
        kSecReturnData: true
    ]

    var item: CFTypeRef?
    let status = SecItemCopyMatching(query as CFDictionary, &item)

    switch status {
    case errSecSuccess:
        break
    case errSecItemNotFound:
        throw KeychainReadError.itemNotFound
    case errSecAuthFailed, errSecUserCanceled, errSecInteractionNotAllowed:
        throw KeychainReadError.authFailed
    default:
        throw KeychainReadError.status(status)
    }

    guard let data = item as? Data,
          let password = String(data: data, encoding: .utf8) else {
        throw KeychainReadError.decodeFailed
    }
    return password
}
```

CLI equivalent (same query):

```bash
security find-generic-password -s "your.service.name" -a "account" -w
```

Notes:
- `kSecReturnData` yields the secret as `Data`. Without it you only get attributes.
- First unlock / ACL may show the system prompt. Headless: `kSecUseAuthenticationUI` / `errSecInteractionNotAllowed`.
- Sandboxed apps need the Keychain Sharing entitlement and a matching access group (`kSecAttrAccessGroup`) to see items they did not create.
- Do not log the returned string.

ObjC same query:

```objc
#import <Security/Security.h>
#import <Foundation/Foundation.h>

NSString *ReadGenericPassword(NSString *service, NSString *account, NSError **error) {
    NSDictionary *query = @{
        (__bridge id)kSecClass: (__bridge id)kSecClassGenericPassword,
        (__bridge id)kSecAttrService: service,
        (__bridge id)kSecAttrAccount: account,
        (__bridge id)kSecMatchLimit: (__bridge id)kSecMatchLimitOne,
        (__bridge id)kSecReturnData: @YES
    };

    CFTypeRef result = NULL;
    OSStatus status = SecItemCopyMatching((__bridge CFDictionaryRef)query, &result);
    if (status != errSecSuccess) {
        if (error) {
            *error = [NSError errorWithDomain:NSOSStatusErrorDomain code:status userInfo:nil];
        }
        return nil;
    }

    NSData *data = CFBridgingRelease(result);
    return [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
}
```
